import android.app.Activity;
import javax.net.ssl.*;import java.net.*;import java.io.*;import java.security.cert.Certificate;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
public class UpdaterStartupTest {
 static AtomicInteger requests=new AtomicInteger();static volatile boolean offline=false;static volatile long version=1;static volatile CountDownLatch hold=null;static int checks;
 static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static void finish(Activity a)throws Exception{Runnable r=a.callbacks.poll(5,TimeUnit.SECONDS);check(r!=null,"network check completes asynchronously");r.run();}
 static void enter(java.lang.reflect.Method resume,java.lang.reflect.Method check,Object updater,String app)throws Exception{resume.invoke(updater);if(app.equals("Foldery")||app.equals("Widgery"))check.invoke(updater,false);}
 public static void main(String[] args)throws Exception{
  URL.setURLStreamHandlerFactory(protocol->!protocol.equals("https")?null:new URLStreamHandler(){protected URLConnection openConnection(URL u){return new HttpsURLConnection(u){public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}public String getCipherSuite(){return "test";}public Certificate[] getLocalCertificates(){return null;}public Certificate[] getServerCertificates(){return null;}public int getResponseCode()throws IOException {requests.incrementAndGet();CountDownLatch h=hold;if(h!=null)try{h.await(4,TimeUnit.SECONDS);}catch(InterruptedException e){throw new IOException(e);}if(offline)throw new IOException("offline");return 200;}public InputStream getInputStream(){String json="{\"schemaVersion\":1,\"app\":\""+args[0].toLowerCase(java.util.Locale.ROOT)+"\",\"status\":\"published\",\"versionCode\":"+version+",\"versionName\":\"new\",\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"downloadUrl\":\"https://github.com/UrySoft/urysoft/releases/download/test/test.apk\"}";return new ByteArrayInputStream(json.getBytes(java.nio.charset.StandardCharsets.UTF_8));}};}});
  Class<?> c=Class.forName((args[0].equals("Foldery")?"cat.urysoft.widgets":args[0].equals("Widgery")?"com.urisoft.widgery":args[0].equals("Minairo")?"com.urysoft.minairo":args[0].equals("NexoMesh")?"com.urysoft.meshchat":"com.urysoft.lumen")+".UrySoftUpdater");java.lang.reflect.Constructor<?> constructor=c.getDeclaredConstructor(Activity.class);constructor.setAccessible(true);Activity activity=new Activity();Object updater=constructor.newInstance(activity);java.lang.reflect.Method resume=c.getDeclaredMethod("resume"),pause=c.getDeclaredMethod("pause"),manual=c.getDeclaredMethod("check",boolean.class);resume.setAccessible(true);pause.setAccessible(true);manual.setAccessible(true);
  enter(resume,manual,updater,args[0]);finish(activity);check(requests.get()==1&&activity.dialogs==0,"startup checks without no-update pop-up");
  pause.invoke(updater);enter(resume,manual,updater,args[0]);finish(activity);check(requests.get()==2,"immediate reopen checks again despite previous success");
  offline=true;pause.invoke(updater);enter(resume,manual,updater,args[0]);finish(activity);check(requests.get()==3&&activity.dialogs==0,"offline startup fails silently");offline=false;
  pause.invoke(updater);enter(resume,manual,updater,args[0]);finish(activity);check(requests.get()==4,"reopen after network failure retries immediately");
  hold=new CountDownLatch(1);pause.invoke(updater);enter(resume,manual,updater,args[0]);manual.invoke(updater,true);enter(resume,manual,updater,args[0]);hold.countDown();hold=null;finish(activity);check(requests.get()==5,"concurrent lifecycle and manual calls share in-flight request");
  version=2;pause.invoke(updater);enter(resume,manual,updater,args[0]);pause.invoke(updater);finish(activity);check(activity.dialogs==0,"background completion cannot display a dialog");enter(resume,manual,updater,args[0]);finish(activity);check(requests.get()==7&&activity.dialogs==1,"return foreground checks and offers newer version");
  manual.invoke(updater,true);finish(activity);check(requests.get()==8&&activity.dialogs==2,"manual check remains available");
  Activity restarted=new Activity();updater=constructor.newInstance(restarted);enter(resume,manual,updater,args[0]);finish(restarted);check(requests.get()==9&&restarted.dialogs==1,"fresh activity startup always checks");
  System.out.println("PASS "+args[0].toLowerCase(java.util.Locale.ROOT)+": "+checks+" lifecycle, offline, concurrency, retry and version-notice checks using production updater.");
 }
}
